import sys


def parse(line):
    fields = []
    cur = []
    i = 0
    n = len(line)
    inq = False
    while i < n:
        c = line[i]
        if inq:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 1
                else:
                    inq = False
            else:
                cur.append(c)
        elif c == '"':
            inq = True
        elif c == ',':
            fields.append(''.join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    fields.append(''.join(cur))
    return fields


data = sys.stdin.read().split('\n')
if data and data[-1] == '':
    data.pop()
for raw in data:
    line = raw.rstrip('\r')
    f = parse(line)
    print("%d: %s" % (len(f), '|'.join('[' + x + ']' for x in f)))
